import{_ as t,o as i,c as h,a5 as o}from"./chunks/framework.CsGesDJn.js";const p=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"feature/admin-management/3-10-11-view-revenue-dasboard/report3_spec.md","filePath":"feature/admin-management/3-10-11-view-revenue-dasboard/report3_spec.md"}'),g={name:"feature/admin-management/3-10-11-view-revenue-dasboard/report3_spec.md"};function r(s,n,l,a,u,c){return i(),h("div",null,[...n[0]||(n[0]=[o("<p><strong>3.10.11 View Revenue Dashboard (Bảng Điều Khiển Doanh Thu Nền Tảng)</strong></p><p><strong>Function Trigger</strong></p><p>Bắt đầu khi Quản trị viên (ADMIN) truy cập trang quản lý tài chính tại /admin/revenue.</p><p><strong>Function Description</strong></p><ul><li><strong>Actors / Roles</strong>: ADMIN. Quản trị viên theo dõi doanh thu và số liệu thanh toán toàn nền tảng.</li><li><strong>Purpose</strong>: Hiển thị chi tiết số liệu doanh thu từ các gói đăng ký dịch vụ (PayOS) và dịch vụ nạp điểm AI Credit.</li><li><strong>Interface</strong>: Bảng Điều Khiển Doanh Thu Nền Tảng (SCR-ADM-10), gồm các thẻ KPI doanh thu (MRR, ARR, Doanh thu lũy kế), biểu đồ doanh thu theo thời gian, biểu đồ cơ cấu nguồn thu và bảng giao dịch gần nhất.</li><li><strong>Data Processing</strong>: Kiểm tra ADMIN; tính MRR/ARR từ quyền thuê bao trả phí đang hiệu lực và tổng hợp riêng thanh toán/hoàn tiền đối soát theo múi giờ báo cáo. Áp dụng giảm giá hiện tại và catalog gói hiện có.</li></ul><p><strong>Screen Layout</strong></p><p>Figure — Bảng Điều Khiển Doanh Thu Nền Tảng (SCR-ADM-10):</p><ul><li>Left/Header: Điều hướng Admin, bộ lọc kỳ, múi giờ UTC / Asia/Ho_Chi_Minh (mặc định) và Xuất PDF.</li><li>Center: Thẻ MRR, ARR, tiền thu gộp, tiền hoàn, thu ròng và số giao dịch thành công. Biểu đồ tách tiền subscription/AI Credit; lọc gói catalog; lịch sử thanh toán/hoàn với trạng thái. Phân biệt MRR tại thời điểm thống kê và tiền thu trong kỳ.</li><li>Buttons: Nút &quot;Làm mới số liệu&quot;, Bộ lọc thời gian (Tháng này, Quý này, Năm nay, Tùy chỉnh), Nút &quot;Xuất Báo cáo Tài chính PDF&quot;.</li><li>Footer: Dấu thời gian đối soát dữ liệu gần nhất và ghi chú bảo mật thanh toán.</li></ul><p><strong>Function Details</strong></p><ul><li><p><strong>Data Specifications</strong></p><ul><li><strong>Input required</strong>: Không có (mặc định hiển thị dữ liệu tháng hiện tại).</li><li><strong>Input optional</strong>: period, startDate, endDate, timezone (UTC/Asia/Ho_Chi_Minh), planId (catalog).</li><li><strong>System data</strong>: mrrAmount, arrAmount, grossReceipts, refunds, netReceipts, subscriptionReceipts, aiCreditReceipts, successfulTransactionCount, transactions, asOf, timezone.</li><li><strong>Output</strong>: Gói dữ liệu JSON doanh thu nền tảng kèm mã HTTP 200 OK.</li></ul></li><li><p><strong>Business Rules</strong></p><ul><li><strong>BR-65</strong>: Chỉ ADMIN xem tài chính toàn nền tảng.</li><li><strong>BR-60</strong>: MRR là giá trị thuê bao trả phí đang hiệu lực quy về tháng sau giảm giá áp dụng; gói năm đóng góp giá năm / 12. ARR = MRR × 12. Tiền thu gộp gồm thanh toán subscription và AI Credit mua lẻ thành công trong kỳ. Hiển thị tiền hoàn riêng; thu ròng = tiền thu gộp − tiền hoàn. AI Credit không vào MRR. Hoàn tiền chỉ đổi MRR khi giá trị/trạng thái thuê bao thay đổi; không trừ hai lần.</li><li><strong>BR-60</strong>: Dùng sự kiện thanh toán/hoàn tiền thành công thật, gồm hoàn một phần. Giao dịch đã hoàn vẫn thuộc tiền thu gộp; khoản hoàn ghi riêng ở lúc hoàn. Thanh toán chờ/thất bại không đóng góp.</li><li><strong>BR-60</strong>: Đổi gói chờ bởi Admin chưa đổi MRR, quota hoặc tiền thu ngay. Kỳ sau vẫn phải thanh toán; thao tác đổi không phải doanh thu.</li><li><strong>BR-80</strong>: Tính tiền chính xác theo quy tắc tiền tệ hiện có; hiện asOf cho MRR và khoảng báo cáo cho tiền thu.</li><li><strong>BR-65</strong>: Lưu thời điểm bằng UTC; báo cáo cho chọn UTC hoặc Asia/Ho_Chi_Minh (mặc định). Tính biên ngày và nhóm ngày/tháng theo múi giờ đã chọn; trả múi giờ trong response, bản xuất và khóa cache.</li><li><strong>BR-82</strong>: System role chỉ gồm ADMIN và USER. Quyền thành viên Agency/Workspace quản lý riêng. Mã gói lấy từ catalog subscription hiện có (hiện tại BASIC, PRO, ENTERPRISE), không tạo danh mục gói cứng khác.</li><li><strong>BR-16</strong>: Audit truy vấn tài chính và xuất báo cáo.</li></ul></li><li><p><strong>Validation</strong></p><ul><li>Người dùng không có quyền ADMIN → Display: MSG39</li><li>Khoảng ngày lọc không có dữ liệu giao dịch → Display: MSG122</li></ul></li></ul><p><strong>Functionalities</strong></p><ul><li><p><strong>Normal Flow</strong></p><ol><li>Admin mở SCR-ADM-10, chọn kỳ, múi giờ và tùy chọn gói catalog.</li><li>Kiểm tra ADMIN và xác định biên báo cáo.</li><li>Tính MRR thuê bao hiện tại quy về tháng và ARR độc lập với ngày thu tiền.</li><li>Tổng hợp thanh toán/hoàn thành công trong kỳ; tách subscription/AI Credit và tính thu ròng.</li><li>Hiển thị giá trị với asOf, kỳ và múi giờ; giữ các tham số khi xuất PDF.</li></ol></li><li><p><strong>Abnormal Cases</strong></p><ul><li>2.a1: Nếu người dùng không có vai trò ADMIN, hệ thống chặn truy cập và hiển thị MSG39.</li><li>3.a1: Nếu khoảng ngày chọn không có dữ liệu phát sinh, hệ thống hiển thị MSG122.</li></ul></li></ul><p><strong>Post-Conditions</strong></p><ul><li>Số liệu doanh thu được hiển thị chính xác và trực quan trên màn hình.</li><li>Dữ liệu đối soát tài chính sẵn sàng để xuất báo cáo PDF khi có yêu cầu.</li></ul>",14)])])}const m=t(g,[["render",r]]);export{p as __pageData,m as default};
